const AB='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function encInt(n){if(n===0n)return '';let s='';while(n>0n){s=AB[Number(n%58n)]+s;n/=58n;}return s;}
function b58enc(buf){let z=0;while(z<buf.length&&buf[z]===0)z++;let acc=0n;for(let i=z;i<buf.length;i++)acc=acc*256n+BigInt(buf[i]);return AB[0].repeat(z)+encInt(acc);}
function bytesRepr(buf){
  let sq=0,dq=0;
  for(const c of buf){ if(c===0x27)sq++; else if(c===0x22)dq++; }
  const q = (sq && !dq) ? '"' : "'";
  let out = "b" + q;
  for(const c of buf){
    if(c===q.charCodeAt(0) || c===0x5c) out += "\\" + String.fromCharCode(c);
    else if(c===0x09) out += "\\t";
    else if(c===0x0a) out += "\\n";
    else if(c===0x0d) out += "\\r";
    else if(c<0x20 || c>=0x7f) out += "\\x" + c.toString(16).padStart(2,'0');
    else out += String.fromCharCode(c);
  }
  return out + q;
}
let seed=987654321;
function rnd(){seed=(seed*1103515245+12345)&0x7fffffff;return seed/0x7fffffff;}
const lines=[];
// deterministic pseudo-random cases, biased toward special bytes
const special=[0,9,10,13,0x22,0x27,0x5c,0x1f,0x20,0x7e,0x7f,0x80,0xff,0x41];
for(let t=0;t<45;t++){
  const len=1+Math.floor(rnd()*12);
  const arr=[];
  for(let i=0;i<len;i++){
    arr.push(rnd()<0.6 ? special[Math.floor(rnd()*special.length)] : Math.floor(rnd()*256));
  }
  lines.push(b58enc(Buffer.from(arr))+"\t"+bytesRepr(Buffer.from(arr))+"\t"+arr.map(x=>x.toString(16).padStart(2,'0')).join(''));
}
console.log(lines.join("\n"));
EOF
